  async function handleNewMessageDebounced_ACU(eventType = 'unknown_acu') {
    logDebug_ACU(
      `New message event (${eventType}) detected for ACU, debouncing for ${NEW_MESSAGE_DEBOUNCE_DELAY_ACU}ms...`,
    );
    clearTimeout(newMessageDebounceTimer_ACU);
    newMessageDebounceTimer_ACU = setTimeout(async () => {
      // [修复] 检查更新是否被用户手动终止，如果是，则跳过本次因终止操作而触发的更新检查
      if (wasStoppedByUser_ACU) {
          wasStoppedByUser_ACU = false; // 重置标志，以允许下一次正常的消息触发更新
          logDebug_ACU('ACU: Skipping update check after user abort.');
          return;
      }
      logDebug_ACU('Debounced new message processing triggered for ACU.');
      if (isAutoUpdatingCard_ACU) {
        logDebug_ACU('ACU: Auto-update already in progress. Skipping.');
        return;
      }
      if (!coreApisAreReady_ACU) {
        logDebug_ACU('ACU: Core APIs not ready. Skipping.');
        return;
      }
      await loadAllChatMessages_ACU();
      // Removed call to applyActualMessageVisibility_ACU();
      await triggerAutomaticUpdateIfNeeded_ACU();
    }, NEW_MESSAGE_DEBOUNCE_DELAY_ACU);
  }

  async function triggerAutomaticUpdateIfNeeded_ACU() {
    logDebug_ACU('ACU Auto-Trigger: Starting check...');

    if (!settings_ACU.autoUpdateEnabled) {
      logDebug_ACU('ACU Auto-Trigger: Auto update is disabled via settings. Skipping.');
      return;
    }

    const apiIsConfigured = (settings_ACU.apiMode === 'custom' && (settings_ACU.apiConfig.useMainApi || (settings_ACU.apiConfig.url && settings_ACU.apiConfig.model))) || (settings_ACU.apiMode === 'tavern' && settings_ACU.tavernProfile);

    if (!coreApisAreReady_ACU || isAutoUpdatingCard_ACU || !apiIsConfigured || !currentJsonTableData_ACU) {
      logDebug_ACU('ACU Auto-Trigger: Pre-flight checks failed.', {
        coreApis: coreApisAreReady_ACU,
        isUpdating: isAutoUpdatingCard_ACU,
        apiConfigured: apiIsConfigured,
        dbLoaded: !!currentJsonTableData_ACU,
      });
      return;
    }
    // 修复：单条问候语不应触发更新。至少需要一次用户输入和一次AI回复才有意义。
    if (allChatMessages_ACU.length < 2) {
      logDebug_ACU('ACU Auto-Trigger: Chat history is too short for a meaningful update cycle (< 2 messages). Skipping.');
      return;
    }

    // 关键修复：直接检查 SillyTavern.chat，因为 TavernHelper.getChatMessages 可能会剥离自定义属性
    const liveChat = SillyTavern_API_ACU.chat;
    if (!liveChat || liveChat.length === 0) {
        logDebug_ACU('ACU Auto-Trigger: Live chat array is empty. Skipping.');
        return;
    }
    const lastLiveMessage = liveChat[liveChat.length - 1];

    // 需求 1: 仅在AI有新回复时触发
    if (lastLiveMessage.is_user) {
        logDebug_ACU('ACU Auto-Trigger: Last message is from user. Skipping update.');
        return;
    }

    // 需求 1.1: 如果最新的AI消息已经包含数据，则跳过
    if (lastLiveMessage.TavernDB_ACU_Data) {
        logDebug_ACU('ACU Auto-Trigger: Last AI message in live chat already contains database data. Skipping update.');
        return;
    }

    // New logic: always trigger if enabled and ready, but use the threshold for context length.
    const currentThreshold = getEffectiveAutoUpdateThreshold_ACU('auto_update');
    const messagesToProcess = allChatMessages_ACU.slice(-currentThreshold);

    if (messagesToProcess.length === 0) {
        logDebug_ACU('ACU Auto-Trigger: No messages to process after slicing.');
        return;
    }

    // 新增：检测机制，token低于阈值不进行填表
    const contextText = messagesToProcess.map(msg => msg.message).join('\n');
    const contextTokenCount = contextText.length; // 简单地使用字符数作为token数的代理
    const tokenThreshold = settings_ACU.autoUpdateTokenThreshold || DEFAULT_AUTO_UPDATE_TOKEN_THRESHOLD_ACU;

    if (contextTokenCount < tokenThreshold) {
        logDebug_ACU(`ACU Auto-Trigger: 上下文token数 (${contextTokenCount}) 低于 ${tokenThreshold} 的阈值，跳过更新。`);
        showToastr_ACU('info', `上下文过短 (约 ${contextTokenCount} tokens)，跳过数据库更新。`);
        return;
    }

    showToastr_ACU('info', `检测到新消息，将触发数据库增量更新。`);
    logWarn_ACU(`ACU: Triggering incremental database update with last ${messagesToProcess.length} messages.`);

    isAutoUpdatingCard_ACU = true;
    const success = await proceedWithCardUpdate_ACU(messagesToProcess); // Pass the array of messages
    isAutoUpdatingCard_ACU = false;

    if (success) {
      logDebug_ACU(`ACU: Incremental update successful.`);
      await loadAllChatMessages_ACU(); // 重新加载消息以更新缓存状态
    } else {
      logError_ACU(`ACU: Incremental update failed.`);
    }
  }

  async function resetScriptStateForNewChat_ACU(chatFileName) {
    // [FIX] Reload all settings to ensure template is not stale for new chats.
    loadSettings_ACU();

    // 修复：当增量更新失败时，chatFileName 可能会暂时变为 null。
    // 之前的逻辑会清除数据库状态，导致“初始化失败”的错误。
    // 新逻辑：如果收到的 chatFileName 无效，则记录一个警告并忽略此事件，
    // 以保留当前的数据库状态，等待一个有效的 CHAT_CHANGED 事件。
    if (!chatFileName || typeof chatFileName !== 'string' || chatFileName.trim() === '' || chatFileName.trim() === 'null') {
        logWarn_ACU(`ACU: Received invalid chat file name: "${chatFileName}". This can happen after an update error. Ignoring event to preserve current state.`);
        // 保持当前状态不变，防止数据库被意外清除
        return;
    }

    logDebug_ACU(`ACU: Resetting script state for new chat: "${chatFileName}"`);

    // 直接使用有效的 chatFileName，不再需要调用 /getchatname 或其他回退逻辑。
    currentChatFileIdentifier_ACU = cleanChatName_ACU(chatFileName);
    allChatMessages_ACU = [];

    logDebug_ACU(
      `ACU: currentChatFileIdentifier FINAL set to: "${currentChatFileIdentifier_ACU}" (Source: CHAT_CHANGED event)`,
    );

    await loadAllChatMessages_ACU();

    if ($popupInstance_ACU) {
      const $titleElement = $popupInstance_ACU.find('h2#updater-main-title-acu');
      if ($titleElement.length)
        $titleElement.html(`数据库自动更新 (当前聊天: ${escapeHtml_ACU(currentChatFileIdentifier_ACU || '未知')})`);
      if ($statusMessageSpan_ACU) $statusMessageSpan_ACU.text('准备就绪');
    }

    if (typeof updateCardUpdateStatusDisplay_ACU === 'function') updateCardUpdateStatusDisplay_ACU();

    await loadOrCreateJsonTableFromChatHistory_ACU();
  }


  async function deleteAllGeneratedEntries_ACU() {
    const primaryLorebookName = await TavernHelper_API_ACU.getCurrentCharPrimaryLorebook();
    if (!primaryLorebookName) return;

    try {
        const allEntries = await TavernHelper_API_ACU.getLorebookEntries(primaryLorebookName);

        const prefixesToDelete = [
            'TavernDB-ACU-ReadableDataTable',     // 全局可读条目
            'TavernDB-ACU-OutlineTable',          // [新增] 总体大纲条目
            '重要人物条目',                       // 重要人物条目
            'TavernDB-ACU-ImportantPersonsIndex', // 重要人物索引条目
            '小总结条目'                          // [新增] 小总结条目
        ];

        const uidsToDelete = allEntries
            .filter(entry => entry.comment && prefixesToDelete.some(prefix => entry.comment.startsWith(prefix)))
            .map(entry => entry.uid);

        if (uidsToDelete.length > 0) {
            await TavernHelper_API_ACU.deleteLorebookEntries(primaryLorebookName, uidsToDelete);
            logDebug_ACU(`Successfully deleted ${uidsToDelete.length} generated database entries for new chat.`);
        }
    } catch(error) {
        logError_ACU('Failed to delete generated lorebook entries:', error);
    }
  }

  const SUMMARY_ECHO_SNIPPETS_ACU = [
      '用150字左右总结本次剧情',
      '将正文简短总结',
      '具体地点 - 具体时间',
      '具体地点 - 日期',
  ];

  function cleanSummaryText_ACU(text, collapseLines) {
      if (!text) return '';
      let cleaned = String(text).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
      if (collapseLines) {
          return cleaned.replace(/\s+/g, ' ').trim();
      }
      return cleaned
          .split('\n')
          .map(line => line.trim())
          .filter(Boolean)
          .join('\n')
          .trim();
  }

  function summaryKeyword_ACU(scene, body) {
      const src = `${scene}|${body}`;
      let hash = 0;
      for (let i = 0; i < src.length; i++) {
          hash = (Math.imul(hash, 31) + src.charCodeAt(i)) | 0;
      }
      return `小结${(hash >>> 0).toString(36)},`;
  }

  function extractSceneSummariesFromText_ACU(text) {
      if (!text || text.indexOf('<scene') === -1 || text.indexOf('<details') === -1) return [];
      // 只认「<scene> 紧挨 <details><summary>」这一对，避免把状态栏之类的 details 当成摘要。一段里有多对时取最后一对。
      const pairRe = /<scene\b[^>]*>([\s\S]*?)<\/scene>\s*<details\b[^>]*>\s*<summary\b[^>]*>[\s\S]*?<\/summary>([\s\S]*?)<\/details>/gi;
      let match;
      let last = null;
      while ((match = pairRe.exec(text))) {
          last = {
              scene: cleanSummaryText_ACU(match[1], true),
              body: cleanSummaryText_ACU(match[2], false),
          };
      }
      if (!last || !last.body || last.body.length < 8) return [];
      if (SUMMARY_ECHO_SNIPPETS_ACU.some(snippet => last.body.includes(snippet) || last.scene === snippet)) return [];
      return [last];
  }

  function messageText_ACU(msg) {
      if (!msg) return '';
      if (typeof msg.message === 'string') return msg.message;
      if (typeof msg.mes === 'string') return msg.mes;
      return '';
  }

  function stripSummaryBlocks_ACU(text) {
      if (!text) return '';
      return text
          .replace(/<scene\b[^>]*>[\s\S]*?<\/scene>\s*<details\b[^>]*>\s*<summary\b[^>]*>[\s\S]*?<\/summary>[\s\S]*?<\/details>/gi, '')
          .trim();
  }

  function findSheetByName_ACU(data, name) {
      if (!data) return null;
      const keys = Object.keys(data).filter(key => key.startsWith('sheet_'));
      for (const key of keys) {
          const table = data[key];
          if (table && table.name && table.name.trim() === name) return table;
      }
      return null;
  }

  function sheetCell_ACU(table, row, headerName) {
      const headers = (table.content[0] || []).slice(1);
      const index = headers.indexOf(headerName);
      if (index < 0) return '';
      return row[index + 1] == null ? '' : String(row[index + 1]);
  }

  function pushRowByHeaders_ACU(table, valueByHeader) {
      const headers = (table.content[0] || []).slice(1);
      const row = [null];
      headers.forEach(header => {
          row.push(valueByHeader[header] != null ? valueByHeader[header] : '');
      });
      table.content.push(row);
  }

  function ingestChatSummariesInto_ACU(data, messages) {
      if (!data || !messages || !messages.length) return 0;
      const summaryTable = findSheetByName_ACU(data, '小总结');
      const outlineTable = findSheetByName_ACU(data, '总体大纲');
      if (!summaryTable || !Array.isArray(summaryTable.content) || !summaryTable.content.length) return 0;

      const existing = new Set();
      summaryTable.content.slice(1).forEach(row => {
          const key = `${sheetCell_ACU(summaryTable, row, '时间跨度').trim()}||${sheetCell_ACU(summaryTable, row, '纪要').trim()}`;
          existing.add(key);
      });

      let added = 0;
      messages.forEach(msg => {
          if (!msg || msg.is_user || msg.role === 'user') return;
          extractSceneSummariesFromText_ACU(messageText_ACU(msg)).forEach(item => {
              const key = `${item.scene}||${item.body}`;
              if (existing.has(key)) return;
              existing.add(key);
              const keyword = summaryKeyword_ACU(item.scene, item.body);
              pushRowByHeaders_ACU(summaryTable, {
                  '时间跨度': item.scene,
                  '纪要': item.body,
                  '编码关键词': keyword,
              });
              if (outlineTable && Array.isArray(outlineTable.content) && outlineTable.content.length) {
                  const outline = item.body.length > 120 ? item.body.slice(0, 120) : item.body;
                  pushRowByHeaders_ACU(outlineTable, {
                      '大纲': outline,
                      '编码关键词': keyword,
                  });
              }
              added++;
          });
      });
      return added;
  }

  function ingestChatSummaries_ACU(messages) {
      const added = ingestChatSummariesInto_ACU(currentJsonTableData_ACU, messages);
      if (added) logDebug_ACU(`Ingested ${added} scene summaries from chat into the database.`);
      return added;
  }

  function renderSummaryContext_ACU() {
      const summaryTable = findSheetByName_ACU(currentJsonTableData_ACU, '小总结');
      const rows = summaryTable && summaryTable.content ? summaryTable.content.slice(1) : [];
      if (!rows.length) {
          return '（对话记录里还没有可用的 scene / details 摘要。）';
      }
      const recent = rows.slice(-SUMMARY_CONTEXT_LIMIT_ACU);
      const omitted = rows.length - recent.length;
      let rendered = '';
      if (omitted > 0) {
          rendered += `（更早的 ${omitted} 条摘要已写入数据库，这里只附最近 ${recent.length} 条。）\n\n`;
      }
      rendered += recent.map(row => {
          const scene = sheetCell_ACU(summaryTable, row, '时间跨度') || '未知场景';
          const body = sheetCell_ACU(summaryTable, row, '纪要');
          return `【${scene}】\n${body}`;
      }).join('\n\n');
      return rendered;
  }

  function messagesContainParsedSummary_ACU(messages) {
      if (!messages) return false;
      return messages.some(msg => msg && !msg.is_user && msg.role !== 'user' && extractSceneSummariesFromText_ACU(messageText_ACU(msg)).length > 0);
  }

  function isFatSnapshot_ACU(data) {
      if (!data || typeof data !== 'object') return false;
      return Object.keys(data).some(key => {
          if (!key.startsWith('sheet_')) return false;
          const sheet = data[key];
          if (!sheet || typeof sheet !== 'object') return false;
          return Object.keys(sheet).some(field => field !== 'uid' && field !== 'name' && field !== 'content');
      });
  }

  function compactTableForStorage_ACU(data) {
      if (!data) return data;
      const compacted = {};
      if (data.mate) compacted.mate = data.mate;
      Object.keys(data).forEach(key => {
          if (!key.startsWith('sheet_')) return;
          const sheet = data[key];
          if (!sheet) return;
          compacted[key] = { uid: sheet.uid, name: sheet.name, content: sheet.content };
      });
      return compacted;
  }

  function rehydrateTableFromStorage_ACU(stored) {
      if (!stored) return stored;
      let template = null;
      try {
          let cleanTemplate = TABLE_TEMPLATE_ACU.trim();
          cleanTemplate = cleanTemplate.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '');
          template = JSON.parse(cleanTemplate);
      } catch (error) {
          logWarn_ACU('Template parse failed during rehydrate, using stored data as-is.', error);
          return JSON.parse(JSON.stringify(stored));
      }
      const merged = JSON.parse(JSON.stringify(template));
      const storedSheets = Object.keys(stored).filter(key => key.startsWith('sheet_')).map(key => stored[key]);
      Object.keys(merged).filter(key => key.startsWith('sheet_')).forEach(key => {
          const sheet = merged[key];
          const match = storedSheets.find(item =>
              (item && item.uid && item.uid === sheet.uid) ||
              (item && item.name && sheet.name && item.name.trim() === sheet.name.trim())
          ) || stored[key];
          if (match && Array.isArray(match.content)) {
              sheet.content = JSON.parse(JSON.stringify(match.content));
          }
      });
      Object.keys(stored).forEach(key => {
          if (key.startsWith('sheet_') && !merged[key]) merged[key] = JSON.parse(JSON.stringify(stored[key]));
      });
      if (stored.mate) merged.mate = stored.mate;
      return merged;
  }

  function stripOldTableSnapshots_ACU(chat, keepMessage) {
      if (!Array.isArray(chat)) return 0;
      const holders = [];
      for (let i = chat.length - 1; i >= 0; i--) {
          if (chat[i] && chat[i].TavernDB_ACU_Data) holders.push(chat[i]);
      }
      const keep = [];
      if (keepMessage && keepMessage.TavernDB_ACU_Data) keep.push(keepMessage);
      holders.forEach(msg => {
          if (keep.length >= 2) return;
          if (!keep.includes(msg)) keep.push(msg);
      });
      let changed = 0;
      chat.forEach(msg => {
          if (!msg || !msg.TavernDB_ACU_Data) return;
          if (!keep.includes(msg)) {
              delete msg.TavernDB_ACU_Data;
              changed++;
              return;
          }
          if (isFatSnapshot_ACU(msg.TavernDB_ACU_Data)) {
              msg.TavernDB_ACU_Data = compactTableForStorage_ACU(msg.TavernDB_ACU_Data);
              changed++;
          }
      });
      return changed;
  }

  function loreKeys_ACU(entry) {
      const raw = entry && (entry.keys || entry.key) || [];
      return Array.isArray(raw) ? raw.map(item => String(item)) : [];
  }

  function buildMarkdownRowEntries_ACU(table, options) {
      if (!table || !table.content || table.content.length < 2) return [];
      const headers = table.content[0].slice(1);
      const keyColumnIndex = headers.indexOf(options.keyHeader);
      if (keyColumnIndex === -1) return null;
      const entries = [];
      table.content.slice(1).forEach((row, index) => {
          const rowData = row.slice(1);
          const keyRaw = rowData[keyColumnIndex];
          if (!keyRaw) return;
          const keys = options.splitKeys
              ? String(keyRaw).split(',').map(item => item.trim()).filter(Boolean)
              : [String(keyRaw).trim()].filter(Boolean);
          if (!keys.length) return;
          const content = options.contentFor(headers, rowData, index);
          entries.push({
              comment: `${options.commentPrefix}${index + 1}`,
              content,
              keys,
              enabled: true,
              type: 'keyword',
              order: options.order,
              prevent_recursion: true,
          });
      });
      return entries;
  }

  const LORE_WRAPPER_PREFIX_ACU = '<最新数据与记录>以下是在这个时间点，当前场景下剧情相关的最新数据与记录，你在进行剧情分析时必须以此最新的数据为准，以下数据与记录的优先级高于其他任何背景设定：\n\n';

  function buildPersonEntries_ACU(importantPersonsTable) {
      const personEntries = buildMarkdownRowEntries_ACU(importantPersonsTable, {
          keyHeader: (importantPersonsTable && importantPersonsTable.content && importantPersonsTable.content[0] || []).slice(1).indexOf('姓名') !== -1 ? '姓名' : '角色名',
          splitKeys: false,
          commentPrefix: '重要人物条目',
          order: 9999,
          contentFor: (headers, rowData) => `${LORE_WRAPPER_PREFIX_ACU}以下是该名角色当前最新的状态，一切关于该角色的剧情都要以此为准：\n\n### ${importantPersonsTable.name}\n\n| ${headers.join(' | ')} |\n|${headers.map(() => '---').join('|')}|\n| ${rowData.join(' | ')} |\n</最新数据与记录>`,
      });
      if (personEntries === null) return null;
      if (!personEntries.length && (!importantPersonsTable || !importantPersonsTable.content || importantPersonsTable.content.length < 2)) {
          return [];
      }
      const headers = importantPersonsTable.content[0].slice(1);
      const nameColumnIndex = headers.indexOf('姓名') !== -1 ? headers.indexOf('姓名') : headers.indexOf('角色名');
      const personNames = importantPersonsTable.content.slice(1)
          .map(row => row.slice(1)[nameColumnIndex])
          .filter(Boolean);
      if (!personNames.length) return personEntries;
      let indexContent = '以下是已经在之前的剧情中登场过的角色：\n\n';
      indexContent += `| ${headers[nameColumnIndex]} |\n|---|\n` + personNames.map(name => `| ${name} |`).join('\n');
      personEntries.push({
          comment: 'TavernDB-ACU-ImportantPersonsIndex',
          content: `${LORE_WRAPPER_PREFIX_ACU}${indexContent}</最新数据与记录>`,
          keys: ['TavernDB-ACU-ImportantPersonsIndex-Key'],
          enabled: true,
          type: 'constant',
          order: 99998,
          prevent_recursion: true,
      });
      return personEntries;
  }

  function buildSummaryEntries_ACU(summaryTable) {
      return buildMarkdownRowEntries_ACU(summaryTable, {
          keyHeader: '编码关键词',
          splitKeys: true,
          commentPrefix: '小总结条目',
          order: 9998,
          contentFor: (headers, rowData, index) => `${LORE_WRAPPER_PREFIX_ACU}### ${summaryTable.name} (条目 ${index + 1})\n\n| ${headers.join(' | ')} |\n|${headers.map(() => '---').join('|')}|\n| ${rowData.join(' | ')} |\n</最新数据与记录>`,
      });
  }

  function buildOutlineEntry_ACU(outlineTable) {
      if (!outlineTable || !outlineTable.content || outlineTable.content.length < 2) return null;
      let content = `### ${outlineTable.name}\n\n`;
      const headers = outlineTable.content[0] ? outlineTable.content[0].slice(1) : [];
      if (headers.length > 0) {
          content += `| ${headers.join(' | ')} |\n`;
          content += `|${headers.map(() => '---').join('|')}|\n`;
      }
      outlineTable.content.slice(1).forEach(row => {
          content += `| ${row.slice(1).join(' | ')} |\n`;
      });
      return {
          comment: 'TavernDB-ACU-OutlineTable',
          content: `<剧情大纲编码索引>\n\n${content.trim()}\n\n</剧情大纲编码索引>`,
          keys: ['TavernDB-ACU-OutlineTable-Key'],
          enabled: true,
          type: 'constant',
          order: 99996,
          prevent_recursion: true,
      };
  }

  async function applyLorebookDiff_ACU(bookName, existingEntries, desiredEntries, activePrefixes) {
      const isActive = entry => entry && entry.comment && activePrefixes.some(prefix => entry.comment.startsWith(prefix) || entry.comment === prefix);
      const existingManaged = (existingEntries || []).filter(isActive);
      const existingByComment = new Map();
      existingManaged.forEach(entry => {
          if (!existingByComment.has(entry.comment)) existingByComment.set(entry.comment, entry);
      });
      const desiredComments = new Set(desiredEntries.map(entry => entry.comment));
      const toDelete = [];
      const seen = new Set();
      existingManaged.forEach(entry => {
          if (seen.has(entry.comment) || !desiredComments.has(entry.comment)) toDelete.push(entry.uid);
          else seen.add(entry.comment);
      });
      const toUpdate = [];
      const toCreate = [];
      desiredEntries.forEach(desired => {
          const current = existingByComment.get(desired.comment);
          if (!current) {
              toCreate.push(desired);
              return;
          }
          const sameContent = (current.content || '') === desired.content;
          const sameKeys = loreKeys_ACU(current).join('\u0001') === loreKeys_ACU(desired).join('\u0001');
          const sameType = (current.type || '') === (desired.type || '');
          if (sameContent && sameKeys && sameType && current.enabled !== false) return;
          toUpdate.push({
              uid: current.uid,
              content: desired.content,
              keys: desired.keys,
              enabled: true,
              type: desired.type,
              prevent_recursion: true,
              order: desired.order,
          });
      });
      if (!toDelete.length && !toUpdate.length && !toCreate.length) {
          logDebug_ACU('Lorebook sync: entries already match, no write.');
          return;
      }
      if (toDelete.length) await TavernHelper_API_ACU.deleteLorebookEntries(bookName, toDelete);
      if (toUpdate.length) await TavernHelper_API_ACU.setLorebookEntries(bookName, toUpdate);
      if (toCreate.length) await TavernHelper_API_ACU.createLorebookEntries(bookName, toCreate);
      logDebug_ACU(`Lorebook sync: delete ${toDelete.length}, update ${toUpdate.length}, create ${toCreate.length}.`);
  }

  async function updateReadableLorebookEntry_ACU(createIfNeeded = false) {
      if (!currentJsonTableData_ACU) {
          logWarn_ACU('Update readable lorebook aborted: currentJsonTableData_ACU is null.');
          return;
      }
      if (!TavernHelper_API_ACU) return;
      const primaryLorebookName = await TavernHelper_API_ACU.getCurrentCharPrimaryLorebook();
      if (!primaryLorebookName) {
          logWarn_ACU('Cannot update lorebook entries: No primary lorebook set.');
          return;
      }

      const { readableText, importantPersonsTable, summaryTable, outlineTable } = formatJsonToReadable_ACU(currentJsonTableData_ACU);
      let allEntries = [];
      try {
          allEntries = await TavernHelper_API_ACU.getLorebookEntries(primaryLorebookName) || [];
      } catch (error) {
          logError_ACU('Failed to read lorebook entries:', error);
          return;
      }

      const desired = [];
      const activePrefixes = ['TavernDB-ACU-OutlineTable'];
      const personEntries = buildPersonEntries_ACU(importantPersonsTable);
      if (personEntries) {
          desired.push(...personEntries);
          activePrefixes.push('重要人物条目', 'TavernDB-ACU-ImportantPersonsIndex');
      }
      const summaryEntries = buildSummaryEntries_ACU(summaryTable);
      if (summaryEntries) {
          desired.push(...summaryEntries);
          activePrefixes.push('小总结条目');
      }
      const outlineEntry = buildOutlineEntry_ACU(outlineTable);
      if (outlineEntry) desired.push(outlineEntry);

      const readableComment = 'TavernDB-ACU-ReadableDataTable';
      const existingReadable = allEntries.find(entry => entry.comment === readableComment);
      if (existingReadable || createIfNeeded) {
          activePrefixes.push(readableComment);
          desired.push({
              comment: readableComment,
              content: `${LORE_WRAPPER_PREFIX_ACU}${readableText}</最新数据与记录>`,
              keys: ['TavernDB-ACU-ReadableDataTable-Key'],
              enabled: true,
              type: 'constant',
              order: 99999,
              prevent_recursion: true,
          });
      }

      try {
          await applyLorebookDiff_ACU(primaryLorebookName, allEntries, desired, activePrefixes);
      } catch (error) {
          logError_ACU('Failed to sync lorebook entries:', error);
      }
  }

  async function saveJsonTableToChatHistory_ACU() {
    if (!currentJsonTableData_ACU) {
        logError_ACU('Save to chat history aborted: currentJsonTableData_ACU is null.');
        return false;
    }

    // 1. Save the raw JSON data to the latest AI message
    const chat = SillyTavern_API_ACU.chat;
    if (!chat || chat.length === 0) {
        logError_ACU('Save failed: Chat history is empty.');
        return false;
    }

    let lastAiMessage = null;
    for (let i = chat.length - 1; i >= 0; i--) {
        if (!chat[i].is_user) {
            lastAiMessage = chat[i];
            break;
        }
    }

    if (!lastAiMessage) {
        logWarn_ACU('Save failed: No AI message found in chat history to attach data to.');
        // This can happen in very new chats. The next AI reply will pick up the data.
        return false;
    }

    // 只保留表内容。聊天里最多留两条快照，避免每轮都把整库历史再存一遍。
    lastAiMessage.TavernDB_ACU_Data = compactTableForStorage_ACU(currentJsonTableData_ACU);
    const removedSnapshots = stripOldTableSnapshots_ACU(chat, lastAiMessage);
    logDebug_ACU(`Attached compact database to the last AI message. Trimmed ${removedSnapshots} older snapshots. Saving chat...`);
    await SillyTavern_API_ACU.saveChat();
    showToastr_ACU('success', '数据库已成功保存到当前聊天记录。');

    return true;
  }

  async function initializeJsonTableInChatHistory_ACU() {
    logDebug_ACU('No database found in chat history. Initializing a new one from template.');

    // 步骤2：安全地在内存中创建数据库
    try {
        let cleanTemplate = TABLE_TEMPLATE_ACU.trim();
        cleanTemplate = cleanTemplate.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '');
        currentJsonTableData_ACU = JSON.parse(cleanTemplate);
        logDebug_ACU('Successfully initialized database in memory.');
    } catch (error) {
        logError_ACU('Failed to parse template and initialize database in memory:', error);
        showToastr_ACU('error', '从模板解析数据库失败，请检查模板格式。');
        currentJsonTableData_ACU = null;
        return false;
    }

    // 步骤3：将空白模板保存到聊天记录，以便首次更新可以找到它
    try {
        const chat = SillyTavern_API_ACU.chat;
        // 在新聊天中，可能还没有AI消息。我们会尝试寻找最后一个，如果没有，数据将暂时保留在内存中。
        let lastAiMessage = null;
        if (chat && chat.length > 0) {
            for (let i = chat.length - 1; i >= 0; i--) {
                if (!chat[i].is_user) {
                    lastAiMessage = chat[i];
                    break;
                }
            }
        }

        if (lastAiMessage) {
            lastAiMessage.TavernDB_ACU_Data = compactTableForStorage_ACU(currentJsonTableData_ACU);
            stripOldTableSnapshots_ACU(chat, lastAiMessage);
            await SillyTavern_API_ACU.saveChat();
            logDebug_ACU('Successfully performed initial save of the blank database to the last AI message.');
        } else {
            logDebug_ACU('Initial save to chat skipped: No AI message found. Data will be attached on first AI reply.');
        }
    } catch (saveError) {
        logWarn_ACU('Failed to perform initial save of the database (this is often normal for new chats and can be ignored):', saveError);
    }

    // 步骤4：删除所有由本插件生成的旧世界书条目
    try {
        await deleteAllGeneratedEntries_ACU();
        logDebug_ACU('Deleted all generated lorebook entries during initialization.');
    } catch (deleteError) {
        logWarn_ACU('Failed to delete generated lorebook entries during initialization:', deleteError);
    }

    return true;
  }

  async function loadOrCreateJsonTableFromChatHistory_ACU() {
    currentJsonTableData_ACU = null; // Reset before loading
    logDebug_ACU('Attempting to load database from chat history...');

    const chat = SillyTavern_API_ACU.chat;
    if (!chat || chat.length === 0) {
      logDebug_ACU('Chat history is empty. Initializing new database.');
      await initializeJsonTableInChatHistory_ACU();
      return;
    }

    // Loop backwards through the chat to find the last message with our data
    for (let i = chat.length - 1; i >= 0; i--) {
      const message = chat[i];
      if (!message.is_user && message.TavernDB_ACU_Data) {
        logDebug_ACU(`Found database data at message index ${i}.`);
        try {
          // 使用深拷贝来加载数据，防止对内存中数据的修改影响到历史记录
          currentJsonTableData_ACU = rehydrateTableFromStorage_ACU(message.TavernDB_ACU_Data);
          logDebug_ACU('Database content successfully loaded from chat history into memory.');
          const trimmedSnapshots = stripOldTableSnapshots_ACU(chat, message);
          if (trimmedSnapshots > 0) {
              try {
                  await SillyTavern_API_ACU.saveChat();
                  logDebug_ACU(`Compacted chat snapshots (${trimmedSnapshots} changes).`);
              } catch (trimError) {
                  logWarn_ACU('Failed to persist compacted chat snapshots:', trimError);
              }
          }
          await updateReadableLorebookEntry_ACU(false); // Sync readable lorebook upon successful load, but don't create it here.
          // 修复：在加载数据成功后，立即通知UI更新
          if (topLevelWindow_ACU.AutoCardUpdaterAPI) {
              topLevelWindow_ACU.AutoCardUpdaterAPI._notifyTableUpdate();
          }
          return; // Exit after finding the most recent data
        } catch (error) {
           logError_ACU(`Failed to process database content from message at index ${i}.`, error);
           // If there's an error, we might want to continue searching or just initialize.
           // For now, we'll continue, but if it's corrupted, we'll end up initializing.
        }
      }
    }

    // If we get here, no data was found in the entire chat history
    logDebug_ACU('No database found in chat history. Initializing a new one.');
    await initializeJsonTableInChatHistory_ACU();
    // 修复：在初始化新数据库后，立即通知UI更新
    if (topLevelWindow_ACU.AutoCardUpdaterAPI) {
        topLevelWindow_ACU.AutoCardUpdaterAPI._notifyTableUpdate();
    }
  }

  function mainInitialize_ACU() {
    console.log('ACU_INIT_DEBUG: mainInitialize_ACU called.');
    if (attemptToLoadCoreApis_ACU()) {
      logDebug_ACU('AutoCardUpdater Initialization successful! Core APIs loaded.');
      toastr.success("数据库自动更新脚本已加载!", "脚本启动");

      addAutoCardMenuItem_ACU();
      loadSettings_ACU();
      if (
        SillyTavern_API_ACU &&
        SillyTavern_API_ACU.eventSource &&
        typeof SillyTavern_API_ACU.eventSource.on === 'function' &&
        SillyTavern_API_ACU.eventTypes
      ) {
        SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes.CHAT_CHANGED, async chatFileName => {
          logDebug_ACU(`ACU CHAT_CHANGED event: ${chatFileName}`);
          await resetScriptStateForNewChat_ACU(chatFileName);
        });
        if (SillyTavern_API_ACU.eventTypes.GENERATION_ENDED) {
            SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes.GENERATION_ENDED, (message_id) => {
                logDebug_ACU(`ACU GENERATION_ENDED event for message_id: ${message_id}`);
                handleNewMessageDebounced_ACU('GENERATION_ENDED');
            });
        }
        const chatModificationEvents = ['MESSAGE_DELETED', 'MESSAGE_SWIPED'];
        chatModificationEvents.forEach(evName => {
            if (SillyTavern_API_ACU.eventTypes[evName]) {
                SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes[evName], async (data) => {
                    logDebug_ACU(`ACU ${evName} event detected. Triggering data reload from chat history.`);
                    clearTimeout(newMessageDebounceTimer_ACU);
                    newMessageDebounceTimer_ACU = setTimeout(async () => {
                        // 修复：不完全重置状态，只重新从聊天记录加载数据库，以防数据不同步
                        await loadOrCreateJsonTableFromChatHistory_ACU();
                    }, 500); // 使用防抖处理快速滑动
                });
            }
        });
        logDebug_ACU('ACU: All event listeners attached using eventSource.');
      } else {
        logWarn_ACU('ACU: Could not attach event listeners because eventSource or eventTypes are missing.');
      }
      if (typeof eventOnButton === 'function') {
        eventOnButton('更新数据库', handleManualUpdateCard_ACU);
        logDebug_ACU(
          "ACU: '更新数据库' button event registered with global eventOnButton.",
        );
      } else {
        logWarn_ACU("ACU: Global eventOnButton function is not available.");
      }
      // 修复：移除启动时的状态重置调用。现在完全依赖于SillyTavern加载后触发的第一个CHAT_CHANGED事件来初始化，避免了竞态条件。
      // [新增修复]：为了解决作为角色脚本加载时可能错过初始CHAT_CHANGED事件的问题，
      // 我们在初始化时主动获取一次当前聊天信息并进行设置。
      // 这确保了无论脚本何时加载，都能正确初始化。
      if (SillyTavern_API_ACU && SillyTavern_API_ACU.chatId) {
          logDebug_ACU(`ACU: Initializing with current chat on load: ${SillyTavern_API_ACU.chatId}`);
          // 修复：将初始加载延迟到下一个事件循环，以避免在SillyTavern完全准备好之前运行初始化，从而解决新聊天的竞态条件。
          setTimeout(() => resetScriptStateForNewChat_ACU(SillyTavern_API_ACU.chatId), 0);
      } else {
          logWarn_ACU('ACU: Could not get current chat ID on initial load. Waiting for CHAT_CHANGED event.');
      }
    } else {
      logError_ACU('ACU: Failed to initialize. Core APIs not available on DOM ready.');
      console.error('数据库自动更新脚本初始化失败：核心API加载失败。');
    }
  }

  // Simplified startup logic based on successful patterns from other plugins.
  // We now rely on jQuery's document ready event, which is standard for Tampermonkey scripts
  // running in the SillyTavern environment. This avoids complex and potentially unreliable
  // timing issues with 'app_ready' for background tasks.
  $(function() {
      console.log('ACU_INIT_DEBUG: Document is ready, attempting to initialize ACU script.');
      mainInitialize_ACU();
  });

  function addAutoCardMenuItem_ACU() {
    const parentDoc = SillyTavern_API_ACU?.Chat?.document
      ? SillyTavern_API_ACU.Chat.document
      : (window.parent || window).document;
    if (!parentDoc || !jQuery_API_ACU) {
      logError_ACU('Cannot find parent document or jQuery for ACU menu.');
      return false;
    }
    const extensionsMenu = jQuery_API_ACU('#extensionsMenu', parentDoc);
    if (!extensionsMenu.length) {
      setTimeout(addAutoCardMenuItem_ACU, 2000);
      return false;
    }
    let $menuItemContainer = jQuery_API_ACU(`#${MENU_ITEM_CONTAINER_ID_ACU}`, extensionsMenu);
    if ($menuItemContainer.length > 0) {
      $menuItemContainer
        .find(`#${MENU_ITEM_ID_ACU}`)
        .off(`click.${SCRIPT_ID_PREFIX_ACU}`)
        .on(`click.${SCRIPT_ID_PREFIX_ACU}`, async function (e) {
          e.stopPropagation();
          const exMenuBtn = jQuery_API_ACU('#extensionsMenuButton', parentDoc);
          if (exMenuBtn.length && extensionsMenu.is(':visible')) {
            exMenuBtn.trigger('click');
            await new Promise(r => setTimeout(r, 150));
          }
          await openAutoCardPopup_ACU();
        });
      return true;
    }
    $menuItemContainer = jQuery_API_ACU(
      `<div class="extension_container interactable" id="${MENU_ITEM_CONTAINER_ID_ACU}" tabindex="0"></div>`,
    );
    const menuItemHTML = `<div class="list-group-item flex-container flexGap5 interactable" id="${MENU_ITEM_ID_ACU}" title="打开数据库自动更新工具"><div class="fa-fw fa-solid fa-database extensionsMenuExtensionButton"></div><span>数据库更新</span></div>`;
    const $menuItem = jQuery_API_ACU(menuItemHTML);
    $menuItem.on(`click.${SCRIPT_ID_PREFIX_ACU}`, async function (e) {
      e.stopPropagation();
      const exMenuBtn = jQuery_API_ACU('#extensionsMenuButton', parentDoc);
      if (exMenuBtn.length && extensionsMenu.is(':visible')) {
        exMenuBtn.trigger('click');
        await new Promise(r => setTimeout(r, 150));
      }
      await openAutoCardPopup_ACU();
    });
    $menuItemContainer.append($menuItem);
    extensionsMenu.append($menuItemContainer);
    logDebug_ACU('ACU Menu item added.');
    return true;
  }

  // --- [新增] 世界书UI交互逻辑 ---
  async function updateWorldbookSourceView_ACU() {
      if (!$popupInstance_ACU) return;
      const source = settings_ACU.worldbookConfig.source;
      const $manualBlock = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-worldbook-manual-select-block`);
      if (source === 'manual') {
          $manualBlock.slideDown();
          await populateWorldbookList_ACU();
      } else {
          $manualBlock.slideUp();
      }
