                        fullReadableText += `### ${table.name}\n\n`;
                        const headers = table.content[0] ? table.content[0].slice(1) : [];
                        if (headers.length > 0) {
                            fullReadableText += `| ${headers.join(' | ')} |\n`;
                            fullReadableText += `|${headers.map(() => '---').join('|')}|\n`;
                        }
                        const rows = table.content.slice(1);
                        if (rows.length > 0) {
                            rows.forEach(row => {
                                const rowData = row.slice(1);
                                fullReadableText += `| ${rowData.join(' | ')} |\n`;
                            });
                        }
                        fullReadableText += '\n';
                    });

                    $dataVisualizationTextarea.val(fullReadableText.trim());
                    $dataVisualizationArea.slideDown();
                }
            });
        }

